function pointInRings(lon, lat, rings) {
  let inside = false;
  for (const ring of rings) {
    for (let i = 0, j = ring.length - 2; i < ring.length; j = i, i += 2) {
      const xi = ring[i];
      const yi = ring[i + 1];
      const xj = ring[j];
      const yj = ring[j + 1];
      if (yi > lat !== yj > lat && lon < ((xj - xi) * (lat - yi)) / (yj - yi) + xi) {
        inside = !inside;
      }
    }
  }
  return inside;
}

/**
 * @returns {string|null} region code containing the point, or null when the
 * point falls outside every boundary (ocean, foreign country, border noise).
 */
export function findRegionCodeAtPoint(lon, lat) {
  for (const [code, { bbox, rings }] of Object.entries(BOUNDARIES)) {
    if (lon < bbox[0] || lon > bbox[2] || lat < bbox[1] || lat > bbox[3]) continue;
    if (pointInRings(lon, lat, rings)) return code;
  }
  return null;
}
